#[allow(dead_code)]
mod common;
use common::{distinct, equal, ordered};
use std::ops::{Add, Neg, Sub};
use timetuck::{Decimal, SimpleDecimalScore};
fn d(text: &str) -> Decimal {
    text.parse().unwrap()
}

#[test]
fn parse_score() {
    assert_eq!(
        "-147.2".parse::<SimpleDecimalScore>().unwrap(),
        SimpleDecimalScore::new(d("-147.2"))
    );
    assert_eq!(
        "-1structural/-147.2".parse::<SimpleDecimalScore>().unwrap(),
        SimpleDecimalScore::from_parts(-1, [d("-147.2")])
    );
}

#[test]
fn of_keeps_scale_of_non_zero_level() {
    assert_eq!(SimpleDecimalScore::new(d("1.0")).score().scale(), 1);
}

#[test]
fn to_short_string() {
    assert_eq!(SimpleDecimalScore::new(d("0.0")).to_short_string(), "0");
    assert_eq!(
        SimpleDecimalScore::new(d("-147.2")).to_short_string(),
        "-147.2"
    );
    assert_eq!(
        SimpleDecimalScore::from_parts(-1, [d("-147.2")]).to_short_string(),
        "-1structural/-147.2"
    );
}

#[test]
fn test_to_string() {
    assert_eq!((SimpleDecimalScore::new(d("0"))).to_string(), "0");
    assert_eq!((SimpleDecimalScore::new(d("0.0"))).to_string(), "0");
    assert_eq!((SimpleDecimalScore::new(d("0.00"))).to_string(), "0");
    assert_eq!((SimpleDecimalScore::new(d("-147.2"))).to_string(), "-147.2");
    assert_eq!(
        (SimpleDecimalScore::from_parts(-1, [d("-147.2")])).to_string(),
        "-1structural/-147.2"
    );
}

#[test]
fn parse_score_illegal_argument() {
    assert!(
        "-147.2hard/-258.3soft"
            .parse::<SimpleDecimalScore>()
            .is_err()
    );
    assert!(
        "-1structural/-147.2hard"
            .parse::<SimpleDecimalScore>()
            .is_err()
    );
}

#[test]
fn feasible() {
    assert!(!(SimpleDecimalScore::from_parts(-1, [d("0")])).is_feasible());
    assert!((SimpleDecimalScore::new(d("0"))).is_feasible());
    assert!((SimpleDecimalScore::new(d("-5"))).is_feasible());
}

#[test]
fn add() {
    assert_eq!(
        SimpleDecimalScore::new(d("20")).add(SimpleDecimalScore::new(d("-1"))),
        SimpleDecimalScore::new(d("19"))
    );
}

#[test]
fn subtract() {
    assert_eq!(
        SimpleDecimalScore::new(d("20")).sub(SimpleDecimalScore::new(d("-1"))),
        SimpleDecimalScore::new(d("21"))
    );
}

#[test]
fn multiply() {
    assert_eq!(
        SimpleDecimalScore::new(d("5.0"))
            .multiply(&d("1.2"))
            .unwrap(),
        SimpleDecimalScore::new(d("6.0"))
    );
    assert_eq!(
        SimpleDecimalScore::new(d("1.0"))
            .multiply(&d("1.2"))
            .unwrap(),
        SimpleDecimalScore::new(d("1.2"))
    );
    assert_eq!(
        SimpleDecimalScore::new(d("4.0"))
            .multiply(&d("1.2"))
            .unwrap(),
        SimpleDecimalScore::new(d("4.8"))
    );
}

#[test]
fn divide() {
    assert_eq!(
        SimpleDecimalScore::new(d("25.0"))
            .divide(&d("5.0"))
            .unwrap(),
        SimpleDecimalScore::new(d("5.0"))
    );
    assert_eq!(
        SimpleDecimalScore::new(d("21.0"))
            .divide(&d("5.0"))
            .unwrap(),
        SimpleDecimalScore::new(d("4.2"))
    );
    assert_eq!(
        SimpleDecimalScore::new(d("24.0"))
            .divide(&d("5.0"))
            .unwrap(),
        SimpleDecimalScore::new(d("4.8"))
    );
}

#[test]
fn power() {
    assert_eq!(
        SimpleDecimalScore::new(d("5.0")).power(2).unwrap(),
        SimpleDecimalScore::new(d("25.0"))
    );
}

#[test]
fn multiply_clamps_negative_scale() {
    assert_eq!(
        SimpleDecimalScore::new(d("1E+2"))
            .multiply(&d("1.5"))
            .unwrap(),
        SimpleDecimalScore::new(d("150"))
    );
}

#[test]
fn divide_clamps_negative_scale() {
    assert_eq!(
        SimpleDecimalScore::new(d("1E+2"))
            .divide(&d("2.0"))
            .unwrap(),
        SimpleDecimalScore::new(d("50"))
    );
}

#[test]
fn power_clamps_negative_scale() {
    assert_eq!(
        SimpleDecimalScore::new(d("1E+2")).power(0).unwrap(),
        SimpleDecimalScore::new(d("1"))
    );
}

#[test]
fn negate() {
    assert_eq!(
        SimpleDecimalScore::new(d("5.0")).neg(),
        SimpleDecimalScore::new(d("-5.0"))
    );
    assert_eq!(
        SimpleDecimalScore::new(d("-5.0")).neg(),
        SimpleDecimalScore::new(d("5.0"))
    );
}

#[test]
fn abs() {
    assert_eq!(
        SimpleDecimalScore::new(d("5.0")).abs(),
        SimpleDecimalScore::new(d("5.0"))
    );
    assert_eq!(
        SimpleDecimalScore::new(d("-5.0")).abs(),
        SimpleDecimalScore::new(d("5.0"))
    );
}

#[test]
fn zero() {
    assert_eq!(SimpleDecimalScore::ZERO, SimpleDecimalScore::new(d("0")));
    assert!(SimpleDecimalScore::new(d("0")).is_zero());
    assert!(!SimpleDecimalScore::new(d("1")).is_zero());
}

#[test]
fn equals_and_hash_code() {
    equal(&[
        SimpleDecimalScore::new(d("-10.0")),
        SimpleDecimalScore::new(d("-10.0")),
        SimpleDecimalScore::new(d("-10.000")),
    ]);
    equal(&[
        SimpleDecimalScore::from_parts(-1, [d("-10.0")]),
        SimpleDecimalScore::from_parts(-1, [d("-10.0")]),
    ]);
    distinct(&[
        SimpleDecimalScore::new(d("-10.0")),
        SimpleDecimalScore::new(d("-30.0")),
        SimpleDecimalScore::from_parts(-1, [d("-10.0")]),
    ]);
}

#[test]
fn compare_to() {
    ordered(&[
        SimpleDecimalScore::from_parts(-1, [d("-300.5")]),
        SimpleDecimalScore::new(d("-300.5")),
        SimpleDecimalScore::new(d("-300")),
        SimpleDecimalScore::new(d("-20.067")),
        SimpleDecimalScore::new(d("-20.007")),
        SimpleDecimalScore::new(d("-20")),
        SimpleDecimalScore::new(d("-1")),
        SimpleDecimalScore::new(d("0")),
        SimpleDecimalScore::new(d("1")),
    ]);
}
